INSERT INTO `books` (`id`, `title`, `slug`, `author_id`, `category_id`, `price_current`, `price_old`, `cover_image`, `discount_percent`, `rating`, `reviews_count`, `is_new`, `is_best_seller`, `created_at`, `updated_at`, `description`, `stock`, `publisher`, `pages`, `publication_year`) VALUES
(1, 'Nhà Giả Kim', 'nha-gia-kim', 1, 1, 79000, 99000, 'https://covers.openlibrary.org/b/isbn/9780062315007-L.jpg', 20, 4.8, 4, 0, 1, '2026-10-04 17:16:37', '2026-10-12 06:09:38', 'Nhà giả kim (tựa gốc tiếng Bồ Đào Nha: O Alquimista) là cuốn tiểu thuyết nổi tiếng nhất của nhà văn Paulo Coelho. Tất cả những trải nghiệm trong chuyến phiêu lưu theo đuổi vận mệnh của chàng chăn cừu Santiago đã giúp cậu thấu hiểu được ý nghĩa sâu xa nhất của hạnh phúc, hòa hợp với vũ trụ và con người.', 117, 'NXB Hội Nhà Văn', 228, 2020),
(2, 'Rừng Na Uy', 'rung-na-uy', 2, 2, 105000, 135000, 'https://covers.openlibrary.org/b/isbn/9780375704024-L.jpg', 22, 4.6, 5, 0, 1, '2026-10-04 17:16:37', '2026-10-12 06:09:38', 'Rừng Na Uy là một trong những tác phẩm kinh điển của Haruki Murakami. Lấy bối cảnh Tokyo những năm 1960, câu chuyện kể về những hoài niệm, tình yêu, sự mất mát và những trăn trở của tuổi trẻ giữa hai bóng hình thiếu nữ Naoko và Midori.', 83, 'NXB Hội Nhà Văn', 552, 2019),
(4, 'Sự Im Lặng Của Bầy Cừu', 'su-im-lang-cua-bay-cuu', 4, 6, 110000, 140000, 'https://covers.openlibrary.org/b/isbn/9780312924584-L.jpg', 21, 4, 4, 0, 1, '2026-10-04 17:16:37', '2026-10-12 06:09:38', 'Một trong những kiệt tác trinh thám tâm lý kinh dị hay nhất mọi thời đại. Cuộc đấu trí căng thẳng giữa nữ đặc vụ FBI Clarice Starling và bác sĩ tâm thần thông thái bệnh hoạn Hannibal Lecter.', 43, 'NXB Lao Động', 380, 2018),
(5, 'Bóng Hình Của Gió', 'bong-hinh-cua-gio', 5, 2, 120000, NULL, 'https://covers.openlibrary.org/b/isbn/9780143034902-L.jpg', NULL, 3.8, 6, 1, 0, '2026-10-04 17:16:37', '2026-10-12 06:09:38', 'Câu chuyện kỳ bí diễn ra tại Barcelona sau Thế chiến thứ hai, nơi cậu bé Daniel được cha dẫn tới Nghĩa địa của những cuốn sách bị quên lãng. Một cuốn sách đưa cậu vào vòng xoáy của đam mê, bí mật đen tối và định mệnh.', 30, 'NXB Văn Học', 540, 2022),
(6, 'Muôn Kiếp Nhân Sinh', 'muon-kiep-nhan-sinh', 6, 3, 168000, 210000, 'https://covers.openlibrary.org/b/isbn/9780735211292-L.jpg', 20, 4.6, 5, 1, 0, '2026-10-04 17:16:37', '2026-10-12 06:09:38', 'Muôn kiếp nhân sinh là bức tranh toàn cảnh về luật Nhân Quả và Luân Hồi, thông qua câu chuyện có thật của một doanh nhân tài chính tại New York với ký ức về nhiều tiền kiếp trải dài từ nền văn minh Atlantis đến Ai Cập cổ đại.', 90, 'NXB Tổng Hợp TP.HCM', 420, 2020),
(7, 'Tội Ác Và Hình Phạt', 'toi-ac-va-hinh-phat', 7, 1, 145000, NULL, 'https://covers.openlibrary.org/b/isbn/9780140449136-L.jpg', NULL, 5, 3, 1, 0, '2026-10-04 17:16:37', '2026-10-12 06:09:38', 'Kiệt tác vĩ đại của đại văn hào Nga Dostoevsky, khắc họa chiều sâu tâm lý giằng xé của chàng sinh viên Raskolnikov sau khi phạm tội sát nhân, hành trình chuộc tội và sự cứu rỗi của tình yêu thương.', 25, 'NXB Văn Học', 680, 2021),
(8, 'Chuyện Con Mèo Dạy Hải Âu Bay', 'chuyen-con-meo-day-hai-au-bay', 8, 5, 49000, 60000, 'https://covers.openlibrary.org/b/isbn/9780143119395-L.jpg', 18, 5, 4, 1, 0, '2026-10-04 17:16:37', '2026-10-12 06:09:38', 'Câu chuyện cảm động về chú mèo mập Zorba tại bến cảng Hamburg và ba lời hứa danh dự: không ăn quả trứng hải âu, chăm sóc chú chim non và dạy nó bay. Cuốn sách gieo vào lòng người đọc bài học về lòng nhân ái và tình yêu thương dị biệt.', 150, 'NXB Hội Nhà Văn', 140, 2022),
