-- ==============================================================================
-- BACKUP DỮ LIỆU ĐẦY ĐỦ CỦA WEBSITE MNM BOOKSTORE (LARAVEL + SQLITE -> MYSQL)
-- Ngày xuất: 2026-10-12 13:17:01
-- Đầy đủ: Users, Roles, Categories, Authors, Books, Orders, Order_Items, Coupons...
-- ==============================================================================

CREATE DATABASE IF NOT EXISTS `mnm_bookstore` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `mnm_bookstore`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- -------------------------------------------------------------
-- Bảng: `users` (13 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(255),
    `email` VARCHAR(255),
    `email_verified_at` TIMESTAMP NULL DEFAULT NULL,
    `password` VARCHAR(255),
    `remember_token` VARCHAR(255),
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL,
    `role` VARCHAR(255),
    `phone` VARCHAR(255),
    `address` VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `roles` (2 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(255),
    `guard_name` VARCHAR(255),
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `permissions` (7 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(255),
    `guard_name` VARCHAR(255),
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `model_has_roles` (2 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `model_has_roles`;
CREATE TABLE `model_has_roles` (
    `role_id` INT,
    `model_type` VARCHAR(255),
    `model_id` INT,
    PRIMARY KEY (`role_id`, `model_type`, `model_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `role_has_permissions` (11 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `role_has_permissions`;
CREATE TABLE `role_has_permissions` (
    `permission_id` INT,
    `role_id` INT,
    PRIMARY KEY (`permission_id`, `role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `categories` (9 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(255),
    `slug` VARCHAR(255),
    `description` LONGTEXT,
    `icon` VARCHAR(255),
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `authors` (76 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `authors`;
CREATE TABLE `authors` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(255),
    `slug` VARCHAR(255),
    `bio` LONGTEXT,
    `avatar` VARCHAR(255),
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `books` (224 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `books`;
CREATE TABLE `books` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `title` VARCHAR(255),
    `slug` VARCHAR(255),
    `author_id` INT,
    `category_id` INT,
    `price_current` INT,
    `price_old` INT,
    `cover_image` VARCHAR(255),
    `discount_percent` INT,
    `rating` DECIMAL(12, 2),
    `reviews_count` INT,
    `is_new` INT,
    `is_best_seller` INT,
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL,
    `description` LONGTEXT,
    `stock` INT,
    `publisher` VARCHAR(255),
    `pages` INT,
    `publication_year` INT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `coupons` (3 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `coupons`;
CREATE TABLE `coupons` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `code` VARCHAR(255),
    `type` VARCHAR(255),
    `value` INT,
    `min_order_value` INT,
    `is_active` INT,
    `expires_at` TIMESTAMP NULL DEFAULT NULL,
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL,
    `usage_limit` INT,
    `used_count` INT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `reviews` (1025 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `reviews`;
CREATE TABLE `reviews` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT,
    `book_id` INT,
    `rating` INT,
    `comment` LONGTEXT,
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
-- Bảng: `orders` (57 bản ghi)
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `order_number` VARCHAR(255),
    `user_id` INT,
    `customer_name` VARCHAR(255),
    `customer_email` VARCHAR(255),
    `customer_phone` VARCHAR(255),
    `shipping_address` VARCHAR(255),
    `shipping_notes` LONGTEXT,
    `payment_method` VARCHAR(255),
    `payment_status` VARCHAR(255),
    `status` VARCHAR(255),
    `subtotal` INT,
    `shipping_fee` INT,
    `discount_amount` INT,
    `total_amount` INT,
    `coupon_code` VARCHAR(255),
    `created_at` TIMESTAMP NULL DEFAULT NULL,
    `updated_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -------------------------------------------------------------
